// Builds the data module for the /app chat function from the Markdown files in app-data/.
// Run: npm run app-data (also runs before every build). Output: netlify/functions/_shared/data.generated.ts
// Edit the Markdown files, never the generated file.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const read = (f) => readFileSync(new URL(`../app-data/${f}`, import.meta.url), 'utf8').replace(/\r\n/g, '\n');

export const FIELD_IDS = [
  'wirtschaft', 'finanzen', 'beratung', 'informatik', 'ki', 'ingenieur', 'naturwiss', 'medizin', 'gesundheit',
  'psychologie', 'jura', 'politik', 'mode', 'design', 'architektur', 'marketing', 'medien', 'lehramt', 'gruendung',
  'sport', 'diplomatie', 'eu', 'internationale-orgs', 'intl-business', 'sprachen',
];

// 1. Prompt core: everything from the coach intro up to the knowledge block placeholders
const prompt = read('prompt.md');
const start = prompt.indexOf('Du bist der Pathfinder-Coach');
const end = prompt.indexOf('# Wissensblock');
if (start < 0 || end < 0) throw new Error('prompt.md: start or end marker not found');
const promptCore = prompt.slice(start, end).trim();

// 2. Field profiles: "## 1. Wirtschaft ..." in the same order as FIELD_IDS
const profiles = read('feldprofile.md');
const profileSections = profiles.split(/\n(?=## \d+\. )/).filter((s) => /^## \d+\. /.test(s));
if (profileSections.length !== FIELD_IDS.length) throw new Error(`feldprofile.md: ${profileSections.length} profiles, expected ${FIELD_IDS.length}`);
const legend = profiles.slice(profiles.indexOf('Kostenlabels'), profiles.indexOf('\n---', profiles.indexOf('Kostenlabels'))).trim();
const crossNote = profiles.slice(profiles.indexOf('## Querhinweis'), profiles.indexOf('\n---', profiles.indexOf('## Querhinweis'))).trim();
const fieldProfiles = profileSections.map((s, i) => `[${FIELD_IDS[i]}] ${s.trim().replace(/^## \d+\. /, '')}`).join('\n\n');

// 3. Knowledge: sections tagged (Feld "id"), the rest is general and always included
const wissen = read('wissen.md');
const sections = wissen.split(/\n(?=## )/).filter((s) => s.startsWith('## '));
const byField = Object.fromEntries(FIELD_IDS.map((id) => [id, []]));
const general = [];
const studium = [];
for (const s of sections) {
  const head = s.split('\n')[0];
  if (/^## (Noch offen|Quellen)/.test(head)) continue; // notes for the team, not for the coach
  // only for mode 4 (Studium), so the other modes do not carry it
  if (/Modus "studium"/.test(head)) {
    studium.push(s.replace(/\n---\s*$/, '').trim());
    continue;
  }
  const m = [...head.matchAll(/Feld "([a-z-]+)"/g)].map((x) => x[1]);
  if (/^## Lehramt, Ergänzung/.test(head)) m.push('lehramt');
  const clean = s.replace(/\n---\s*$/, '').trim();
  if (m.length) m.forEach((id) => byField[id]?.push(clean));
  else general.push(clean);
}

// 3b. Universities for mode 4: one line each, so the coach can name real ids in [[KARTE: ...]]
const angebote = JSON.parse(read('angebote.json'));
const hochschulListe = angebote
  .filter((o) => o.typ === 'hochschule' || o.typ === 'studiengang')
  .map((o) => `${o.id} | ${o.name} | ${o.land}, ${o.ort} | ${o.rechtsform ?? ''} | ${o.kosten_label ?? 'Kosten siehe Karte'} | Felder: ${o.felder.join(',')}`)
  .join('\n');

// 3c. All offers, one short line each: the ids the coach may use in ids= (every mode)
const angebotsIndex = angebote
  .map((o) => `${o.id} | ${o.name} | ${o.typ} | ${o.land} | Frist: ${o.frist ?? 'keine feste Frist'} | Quelle: ${o.anbieter} | geprüft: ${o.zuletzt_geprueft}`)
  .join('\n');

// 3b. Dashboard content (app-data/dashboard.json): the whole file goes into the coach's knowledge
const dash = JSON.parse(read('dashboard.json'));
const verified = (d) => (d ? `geprüft: ${d}` : 'noch nicht auf der Quellseite geprüft');
const dashWissen = [
  'Neuigkeiten (id | Meldung | Quelle | Link | Prüfung):',
  ...(dash.ticker ?? []).map((t) => `${t.id} | ${t.text} | ${t.source} | ${t.url} | ${verified(t.lastVerified)}`),
  dash.bigNews?.title ? `\nGroße Neuigkeit (id ${dash.bigNews.id}, Quelle ${dash.bigNews.source}, ${dash.bigNews.url}, ${verified(dash.bigNews.verified)}):\n${dash.bigNews.title}\n${dash.bigNews.body}` : '',
  dash.dayInLife?.markdown ? `\nArtikel (id ${dash.dayInLife.id}, Quellen im Artikel):\n${dash.dayInLife.markdown.trim()}` : '',
]
  .filter(Boolean)
  .join('\n');

// 4. Templates (Teil A) and approved tips (Teil B)
const vr = read('vorlagen-recht.md');
const teilA = vr.slice(vr.indexOf('## Teil A'), vr.indexOf('## Teil B')).replace(/\n---\s*$/, '').trim();
const teilB = vr.slice(vr.indexOf('## Teil B'), vr.indexOf('## Teil C')).replace(/\n---\s*$/, '').trim();

const out = `// GENERATED by scripts/build-app-data.mjs from app-data/*.md. Do not edit by hand.
export const FIELD_IDS = ${JSON.stringify(FIELD_IDS)} as const;
export const PROMPT_CORE = ${JSON.stringify(promptCore)};
export const COST_LEGEND = ${JSON.stringify(legend)};
export const CROSS_NOTE = ${JSON.stringify(crossNote)};
export const FIELD_PROFILES = ${JSON.stringify(fieldProfiles)};
export const WISSEN_GENERAL = ${JSON.stringify(general.join('\n\n'))};
export const WISSEN_BY_FIELD: Record<string, string> = ${JSON.stringify(Object.fromEntries(Object.entries(byField).map(([k, v]) => [k, v.join('\n\n')])))};
export const VORLAGEN = ${JSON.stringify(teilA)};
export const TIPPS_ALLGEMEIN = ${JSON.stringify(teilB)};
export const WISSEN_STUDIUM = ${JSON.stringify(studium.join('\n\n'))};
export const HOCHSCHUL_LISTE = ${JSON.stringify(hochschulListe)};
export const ANGEBOTS_INDEX = ${JSON.stringify(angebotsIndex)};
export const DASHBOARD_WISSEN = ${JSON.stringify(dashWissen)};
`;
mkdirSync(new URL('../netlify/functions/_shared/', import.meta.url), { recursive: true });
writeFileSync(new URL('../netlify/functions/_shared/data.generated.ts', import.meta.url), out);
// 5. CV and portfolio templates (vorlagen/, unchanged files) for /api/vorlage, logged-in people only
const VORLAGEN = [
  { id: 'schueler', datei: 'Lebenslauf-Vorlage-1-Schueler.docx' },
  { id: 'wirtschaft', datei: 'Lebenslauf-Vorlage-2-Wirtschaft-Finanzen-Beratung.docx' },
  { id: 'technik', datei: 'Lebenslauf-Vorlage-3-Technik-Informatik-Naturwissenschaften.docx' },
  { id: 'kreativ', datei: 'Portfolio-Vorlage-4-Kreativ-Medien-Design.pptx' },
];
const vorlagen = VORLAGEN.map((v) => ({ ...v, base64: readFileSync(new URL(`../vorlagen/${v.datei}`, import.meta.url)).toString('base64') }));
writeFileSync(
  new URL('../netlify/functions/_shared/vorlagen.generated.ts', import.meta.url),
  `// GENERATED by scripts/build-app-data.mjs from vorlagen/. Do not edit by hand.\nexport const VORLAGEN_DATEIEN: { id: string; datei: string; base64: string }[] = ${JSON.stringify(vorlagen)};\n`,
);

// 6. Placeholder for the mentor page HTML; scripts/hide-mentor.mjs fills it after vite build
writeFileSync(
  new URL('../netlify/functions/_shared/mentor-page.generated.ts', import.meta.url),
  "// GENERATED placeholder; scripts/hide-mentor.mjs writes the built page here after vite build.\nexport const MENTOR_HTML = '';\n",
);

const empty = FIELD_IDS.filter((id) => !byField[id].length);
console.log(`app data: ${FIELD_IDS.length} profiles, ${sections.length} knowledge sections, ${general.length} general${empty.length ? `, no knowledge section for: ${empty.join(', ')}` : ''}`);
